import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from '/root/data/object.js';
import { mkdirSync, writeFileSync } from 'fs';
import { join, dirname } from 'path';

// Create output directories
mkdirSync('/root/output/part_meshes', { recursive: true });
mkdirSync('/root/output/links', { recursive: true });

// Create the scene
const root = createScene();
const exporter = new OBJExporter();

// Helper function to recursively find meshes and groups
function traverseScene(node, parentPartName) {
    const results = [];

    if (node.isMesh) {
        results.push({
            type: 'mesh',
            name: node.name,
            partName: parentPartName,
            node: node
        });
    } else if (node.isGroup) {
        // This is a group - it becomes a "link"
        results.push({
            type: 'group',
            name: node.name,
            partName: node.name,
            node: node
        });
        // Also traverse children for meshes
        node.children.forEach(child => {
            const childResults = traverseScene(child, node.name);
            results.push(...childResults);
        });
    }

    return results;
}

// Traverse the scene
const allItems = traverseScene(root, 'root');

console.log('Found items:');
allItems.forEach(item => {
    console.log(`  ${item.type}: ${item.name} (part: ${item.partName})`);
