        const fileName = `${meshItem.name}.obj`;
        const filePath = join(partDir, fileName);
        writeFileSync(filePath, objData);
        console.log(`Exported mesh: ${filePath}`);
    });
});

// Export groups to links
const groups = allItems.filter(item => item.type === 'group');
groups.forEach(groupItem => {
    // Export the group itself
